// QueryRepoConfig queries the repo_config edge of a WebhookDeadLetter.
func (c *WebhookDeadLetterClient) QueryRepoConfig(wdl *WebhookDeadLetter) *RepoConfigQuery {
	query := (&RepoConfigClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := wdl.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(webhookdeadletter.Table, webhookdeadletter.FieldID, id),
			sqlgraph.To(repoconfig.Table, repoconfig.FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, webhookdeadletter.RepoConfigTable, webhookdeadletter.RepoConfigColumn),
		)
		fromV = sqlgraph.Neighbors(wdl.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

